insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('79c89303-fe65-481b-8506-11cd45eaed32', 'ja', '雰囲気は良いのに、離れたままでいます。どんなリスクがありますか？', '["関心がありすぎるように見える", "彼女を居心地悪くさせる", "言葉とは裏腹に、関心がないと伝わる", "進み方が速すぎる"]'::jsonb, '距離が合っていないと、言葉で伝えた関心が損なわれることがあります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f7200ef5-2102-4d79-abd9-e518cc3c8af8', 'ja', '小さく一歩近づくと、彼女がさりげなく一歩下がります。これはどういう意味ですか？', '["今は、もっとスペースが必要", "自信を持って粘ってほしいと思っている", "こちらを試している", "こちらをまったく好きではない"]'::jsonb, '一歩下がるのは、拒絶ではなく、情報です。スペースを空けて、合わせ直しましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a9930259-a42a-49fb-bdd4-9d319fe4fd04', 'ja', '距離の近さをめぐって、居心地の悪さを生む間違いは、どれですか？', '["打ち解ける前に、近づくこと", "彼女の体の反応を無視すること", "距離を少しずつ調整すること", "彼女が身を寄せているのに、固まったままでいること"]'::jsonb, '居心地の悪さは、相手の反応を無視したり、それに応えなかったりすることから生まれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c56a1006-a63d-4532-801e-49829be4ccd2', 'ja', '体のミラーリングは、何を伝える助けになりますか？', '["まねによる、惹かれる気持ち", "支配とコントロール", "人と一緒にいるうえでの、安全と安心", "姿勢による自信"]'::jsonb, 'ミラーリングは、無意識のレベルで、親しみと心地よさを伝え、打ち解けるのを助けます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9a5612de-f9a6-4bc1-bcbb-29d29d0b1f91', 'ja', '彼女は、会話のあいだ、静かにゆっくり話します。何を合わせるべきですか？', '["彼女を元気づけるために、声を大きくする", "もとの大きな声のままでいる", "流れを保つために、早口で話す", "声を落とし、ペースをゆっくりにする"]'::jsonb, '彼女のエネルギーとトーンに合わせると、無意識のうちに打ち解けていきます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7dc61f4a-f296-4e9b-ae8f-01bd4a923b88', 'ja', '彼女がこちらをミラーリングしているかもしれないサインは、どれですか？', '["こちらが姿勢を変えたあと、似た姿勢を取る", "こちらの話すペースに合わせる", "質問が増える", "体の向きを、こちらへ向け直す"]'::jsonb, '体とエネルギーがそろうことは、多くの場合、心地よさと関わりを示しています。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('525d7416-b2f1-4458-807f-26c8a8bd7bc8', 'ja', '駆け引きの中で、触れることの一番の目的は何ですか？', '["できるだけ早く、身体的に距離を縮めること", "彼女の境界線を試すこと", "すでにある気持ちのつながりを、強めること", "会話の代わりにすること"]'::jsonb, '触れることがうまくいくのは、すでにある打ち解けた空気を支えるときです。それを新しくつくろうとするときではありません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5136a469-f474-4b76-bc20-841071ccf772', 'ja', '彼女は言葉では関わり続けていますが、触れることには一度も応えず、受け入れてもいません。どうするべきですか？', '["抵抗を破るために、触れる回数を増やす", "なぜ応えないのかを、直接尋ねる", "触れるのは控えて、言葉でのやり取りを続ける", "すぐにやり取りを終える"]'::jsonb, '体での反応が返ってこないのは、触れることがまだ歓迎されていないという意味です。無理強いせずに、合わせましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('efe69dc3-5d6a-4f17-b046-2263cec2230f', 'ja', '軽く触れ始めるのにふさわしいのは、どんな瞬間ですか？', '["彼女が身を寄せてきたり、近くにとどまったりしているとき", "彼女が短く、礼儀正しい返事をしているとき", "その場を一緒に移動しているとき"]'::jsonb, '触れるのは、彼女が心を開いていて、二人の流れがあるときに合わせるべきです。どちらともつかないときや、関心がないときではありません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('249a63f3-79dc-45b1-b433-50465a7a107d', 'ja', '簡単にはなびかない姿勢は、なぜ駆け引きのいつもの構図をひっくり返すのですか？', '["追いかけても、入れ込みすぎてもいないことを示すから", "自分なりの基準を持っていることを伝えるから", "一方的に追う形ではなく、釣り合いを生むから", "上のすべて"]'::jsonb, '簡単にはなびかない姿勢は、彼女が承認を当然のものとして待つ形から、お互いに選び合う形へと変えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('95ad96b3-d2ef-411c-b521-ec1a1bc7d496', 'ja', '彼女が、インスタで気づかれることがどれほど多いかを話します。自分の軸を保てるのは、どれですか？', '["「すごいですね。きっと、すごく人気があるんですね」", "「じゃあ、サインをもらっておいたほうがいいですか？」", "「フォロワーは何人いるんですか？」", "「それだけ注目されて当然ですよ」"]'::jsonb, '軽く言い返すことで、無条件に感心しているわけではないと伝わり、構図がひっくり返ります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7440e677-e76b-4b16-a0f9-213ae82c821a', 'ja', '健全な「簡単にはなびかない」ひと言の例は、どれですか？', '["「納得させてもらわないと」", "「それは、すごくないですね」", "「どうでしょう。こちらは、なかなか手ごわいですよ」", "「そんなに特別じゃないですよ」"]'::jsonb, '簡単にはなびかない姿勢は、軽く挑むものであって、決して相手を退けたり、おとしめたりするものではありません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a91f07b0-5946-49ce-804d-b862552b9592', 'ja', 'やり取りの中で、性的な緊張感を生む助けになるものは何ですか？', '["深い話題", "はっきりした、先の読める感じのよさ", "絶え間ない安心の言葉", "意図をめぐるあいまいさ"]'::jsonb, '緊張感は、可能性から生まれます。意図が宣言されるのではなく、にじんでいるとき、注意は研ぎ澄まされます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('93982613-1848-48bb-b22b-59bd8c12b62f', 'ja', '性的な緊張感を生む助けになるのは、どれですか？', '["心地よいと感じるより、ひと呼吸長く目を合わせる", "彼女がはっきり楽しんでいるなら、腕に触れた手を少しだけそのままにする", "彼女がリラックスしたままでいる限り、少しだけ近くに立つ", "上のすべて"]'::jsonb, '緊張感は、近さと間の、小さく意図のある瞬間を通じて高まります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('67379ba9-deb9-45a2-b30c-f9b26b01536d', 'ja', '緊張感を生みやすいひと言は、どれですか？', '["「それは、いい意見ですね」", "「じっと見ないようにしているんですが、難しいですね」", "「好きなことを話しているとき、きらっとするものがありますね」", "「どうしてその飲み物にしたんですか？」"]'::jsonb, '心を動かされていることを遊び心を込めて認めたり、きらめきに触れたりすることは、あからさまにならずに、惹かれていることをにじませます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('43a061f7-1ccd-4592-8e5d-035717e37189', 'ja', '会話の中での、話題の再登場や二人だけの冗談の一番の目的は何ですか？', '["知性と記憶力を示すこと", "止まった会話を、もう一度始めること", "連続性と、分かち合うつながりを生むこと", "確認のために、彼女の言ったことを繰り返すこと"]'::jsonb, 'これらは、二人の歴史があるという感覚を生み、関係を「知らない人同士」から「内輪の二人」へと変えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('344744cd-ace9-45d2-96db-317d056f2f2f', 'ja', '話題の再登場は、なぜ効果的なのですか？', '["前に出た内容を、ユーモアや遊び心のあるひねりで広げるから", "ばらばらの話題ではなく、つながりを生むから", "会話が、ただ続いているのではなく、積み重なっていると感じさせるから", "上のすべて"]'::jsonb, '覚えていてもらえると、人は「ちゃんと見てもらえている」と感じ、安心感とつながりが深まります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7a584c7b-29ae-4ef4-8faf-ee465bb72e66', 'ja', '話題の再登場や二人だけの冗談の、良い材料になるのはどんな瞬間ですか？', '["彼女が言った、ちょっとした冗談", "彼女が口にした、ささいな好みや癖", "個人的な悩み", "軽い意見や、大げさな言い方"]'::jsonb, '話題の再登場は、軽くて、遊び心があり、その人らしさが表れた内容で、一番うまくいきます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0395cf63-6575-4c9c-aaa2-83805005ade7', 'ja', '彼女が、人の星座を当てるのが得意だと言います。どうすれば遊びの勝負にできますか？', '["自分の星座を、そのまま教える", "星占いは当たらないと言う", "なぜそれを信じているのかを、まじめに尋ねる", "「じゃあ、どうぞ。当ててみてください」"]'::jsonb, '遊び心のある当てっこに誘って、二人で分かち合う緊張感と軽い掛け合いに火をつけましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('061b4ffe-6aea-49da-b29e-1976fc8c62a3', 'ja', '「何を頼むんですか？」と「何を頼むか、当てられると思いますよ」。より相性の良さを生むのは、どちらですか？', '["前者。彼女の好みへの、純粋な関心を示すから", "後者。遊びの勝負が、関わりと楽しさを生むから", "前者。打ち解けるには、こちらのほうが良いから", "後者。自信を示すから"]'::jsonb, '当てっこは、彼女の参加が必要な遊びの勝負で、エネルギーを生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0640bea3-7134-4d3d-bbd1-a2dd404d8c97', 'ja', '彼女が、笑いながら近くに寄ってきます。一番良い対応はどれですか？', '["読み違えないように、固まる", "安全のために、一歩下がる", "落ち着いて、彼女の近さに合わせる", "話題を変える"]'::jsonb, '彼女の動きに合わせると、やり取りがそろったまま、心地よく保たれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0dcb3ce2-da4e-48c3-8c5b-7ded4177d531', 'ja', '彼女が、こちらの料理下手をからかい返してきます。次に何ができますか？', '["身構えて、言い訳をする", "すぐに話題を変える", "笑って、彼女のからかいに遊び心で乗る", "もっと本気で、彼女をからかう"]'::jsonb, '遊び心を返し合えることは、心の余裕を示し、相性の良さを育てます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0f0fa46d-8699-4a6c-9b7b-2fe8afa91fe5', 'ja', '彼女が、珍しい趣味について熱心に話します。一番良い褒め言葉は、どれですか？', '["「個性的ですね」", "「それにどれだけ夢中なのかが、すごく伝わってきて、いいなと思います」", "「面白い趣味をお持ちですね」", "「わくわくしているとき、魅力的ですね」"]'::jsonb, '彼女が自分で選んだものをどう表現しているかに絞った言葉で、そのエネルギーを大切に思っていることが伝わります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('14f120e4-9b66-4b46-81d5-b125235fb2f5', 'ja', '性的な緊張感は、感じのいい会話とどう違いますか？', '["まじめな話題と、深い打ち明け話に頼る", "言葉以外の合図や間を、いっさい避ける", "意図について、かすかな不確かさを持ち込む", "関係を、完全に先の読めるものに保つ"]'::jsonb, '火花は、すべてを明らかにしないまま、「その先」をにじませることから生まれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('17429248-a6f9-42cf-a924-9553dec0b010', 'ja', '同じ言葉を、感じのいいものから恋愛的な含みのあるものに変える要素は、どれですか？', '["ゆっくりした言い方と、やわらげた声", "速いペースと、そらした視線", "ほほえんで、目を合わせたままでいること", "そのあと、その瞬間に余白を残すこと"]'::jsonb, 'その場にいる姿勢とタイミングが、内容を変えずに、熱を加えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1bcaa8b7-9201-4ec7-bab9-cd622fb9b421', 'ja', '緊張感を生みやすいひと言は、どれですか？', '["「落ち着いた雰囲気がありますね。いいなと思います」", "「面白いですね。もっと聞かせてください」", "「それで、お仕事は何をしているんですか？」", "「その目の合わせ方、好きです」"]'::jsonb, '相手の雰囲気や、惹かれていることについてのひと言は、無理強いせずに意図を伝えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1e531297-8fe5-432d-9e8a-8bb1970f99ba', 'ja', '目を合わせ続けることは、生理的に、なぜ強い力を持つのですか？', '["人の中での優位を、自然に示すから", "オキシトシンが分泌され、心拍数が上がり、親密さの感覚が生まれるから", "気持ちのつながりを築く、無防備さを生むから"]'::jsonb, '体は、まずアイコンタクトに反応します。それが、親密さのサインを自然に高めます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1e723f5c-f299-44f4-844c-f7190b8f4c42', 'ja', '会話はうまくいっていて、彼女がいつもより長く目を合わせてきます。どうするべきですか？', '["質問をするために、視線を外す", "小さくほほえんで見つめ返し、その瞬間を長引かせる", "余白を与えるために、目をそらす", "早く距離を縮めるために、大げさに見つめる"]'::jsonb, '続く視線に合わせることは、言葉なしに親密さを生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2bcd40a3-8939-4555-8f99-7c394079b7a0', 'ja', '具体的で、彼女の選んだことに向けた褒め言葉は、なぜより強いつながりを生むのですか？', '["彼女の努力を、本当に認めてもらえたと感じられるから", "彼女が自分で決められることに、気づいたと示すから", "彼女の外見を、直接評価するから"]'::jsonb, '生まれ持ったものではなく、彼女という人そのものを見てもらえたと感じさせます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2d067124-8ee8-41b8-b580-f480159f861e', 'ja', '会話の間に、彼女がまっすぐこちらを見ます。どうするべきですか？', '["気まずさを避けるために、さっと目をそらす", "ほほえまずに、強く見つめる", "下を向いて、話し続ける", "やわらかくほほえんで、落ち着いて見つめ返す"]'::jsonb, '彼女は、見つめ合うきっかけをつくっています。緊張して目をそらさずに、見つめ返しましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2fc0d39c-22da-4308-8ee9-4ab4c88299d2', 'ja', '相手を尊重した駆け引きを最もよく支える考え方は、どれですか？', '["「押さなければ、チャンスを逃す」", "「断られるのは、何か間違ったことをしたからだ」", "「自信とは、決して引かないことだ」", "「すべてのやり取りが、続くべきものとは限らない」"]'::jsonb, '尊重は、関心を持たれないことがふつうのことであり、自分の失敗ではないと受け入れることから始まります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('34e3a8a0-43de-4673-af81-d73381d0ceba', 'ja', '彼女が、人の出身地を当てるのが得意だと言います。遊びの勝負として、次に何ができますか？', '["自分の出身地を、そのまま教える", "彼女の特技を褒める", "彼女の旅行について、まじめに尋ねる", "「じゃあ、証明してください。どこの出身か、当ててみてください」"]'::jsonb, '遊び心のある当てっこに誘って、お互いの関わりと、からかい合いを生みましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('36c3a4cc-1b9f-42ea-a62f-551942c80f5d', 'ja', '駆け引きの中で、軽い勝負を効果的にするものは何ですか？', '["何もかかっていない、気楽な掛け合いにつながる勝負であること", "自分を証明するための、大きな賭け", "彼女の知識を、本気で試すこと", "どちらか一人が、はっきり勝つこと"]'::jsonb, 'かかっているものが小さいと、楽しさが保たれ、どちらの結果になっても、つながりの燃料になります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('37dce606-feeb-4072-baf2-17e1f94a6f8e', 'ja', '彼女が、カフェのお客さんたちについて、気の利いた観察を話します。次に何と言えますか？', '["「目がきれいですね」", "「今日、素敵ですね」", "「面白い方ですね」", "「面白い言い方ですね。それは気づきませんでした」"]'::jsonb, '彼女の見方に直接結びついていて、「本当に見てもらえている」と感じさせます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('384c4054-61db-4bdb-b2c8-91998d08cbee', 'ja', '目を合わせ続けることは、どんな効果を生むことがありますか？', '["親密さの感覚が増す", "生理的な高ぶり", "関心が、はっきり伝わる", "言葉で応えなければという、人付き合い上のプレッシャー"]'::jsonb, 'アイコンタクトは、反応を無理強いすることなく、言葉を使わずに関心を伝えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('39d71381-3505-4e35-9880-fe45c1d756bb', 'ja', '話題の再登場や二人だけの冗談は、なぜ会話の中でつながりを強めるのですか？', '["二人のあいだに、二人だけの糸をつくるから", "本当に聞いていたことを示すから", "共通の話題と、なじみの感覚を生むから", "上のすべて"]'::jsonb, '話題の再登場は、知らない人同士を、共通の歴史を持つ二人へと、すばやく変えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3adb725c-dd19-430c-9522-0dfd8285559a', 'ja', '彼女が、料理が苦手だと言います。遊び心のある返しは、どれですか？', '["「じゃあ、夕食はカップ麺ですか？」", "「大丈夫ですよ。料理は、誰にでも向いているわけではないですから」", "「それは残念ですね。こちらは、よく料理をするので」", "「どれくらい苦手なんですか？お湯を焦がしてしまうくらい？」"]'::jsonb, 'からかいがうまくいくのは、軽い雰囲気を保ち、彼女が返すのを招くときです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3cfd9dfa-fc1f-49af-862d-aea72f90adc9', 'ja', '彼女が、気まずい場面を、品よくユーモアを交えて切り抜けます。何と言えますか？', '["「今の切り抜け方、見事でしたね」", "「完璧ですね」", "「笑顔が素敵ですね」", "「大したことじゃなかったですよ」"]'::jsonb, 'その場での、彼女の人付き合いのうまさと選択を認めています。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('405b2702-ed84-4c3b-9a21-77729ea9f2d4', 'ja', '彼女がメニューを見ながら、「私、何でも考えすぎちゃうんです」と言います。一番良い、いたずらっぽい返しはどれですか？', '["「それは、よくあることですよ」", "「何と何で迷っているんですか？」", "「そのうち決まりますよ」", "「わかります。これは明らかに、生きるか死ぬかの選択ですからね」"]'::jsonb, '大げさな言い方に温かさが加わると、感心させようとしなくても、ユーモアとリズムが生まれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('44e9bef3-c0f2-4d31-a3a2-481c50c7d9d5', 'ja', '緊張感を生みやすいひと言は、どれですか？', '["「それは面白い話ですね」", "「お仕事のこと、もっと聞かせてください」", "「その笑顔、何か惹かれるものがありますね…」", "「すごく温かい雰囲気がありますね」"]'::jsonb, '彼女の笑顔や雰囲気についてのやさしいひと言は、惹かれていることをにじませ、かすかな熱を生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('450fc086-463d-40c5-9ce4-77e9a664a8e7', 'ja', '彼女が「このコーヒー、高すぎますよね」と言います。次に何と言えますか？', '["「ええ、どこも値段がすごいですよね」", "「家でいれたほうがいいですよ」", "「でも、そのプレミアムブレンドに見合う方ですから」", "「いくらだったんですか？」"]'::jsonb, '冗談に包んだいたずらっぽい褒め言葉は、駆け引きのエネルギーに火をつけます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4684c791-9598-4381-9511-739d9afdfead', 'ja', 'ユーモアがうまく届いたことを示す反応は、どれですか？', '["心から笑う", "遊び心を込めて、こちらを訂正する", "冗談を返してくる", "短く、礼儀正しい返事をする"]'::jsonb, '関わりと、同じだけ返ってくることは、青信号です。礼儀正しい短い返事は、そうではありません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4962a3a5-8566-4b58-aafd-36f4a302ce53', 'ja', 'やり取りのあいだずっと離れすぎていると、なぜ惹かれる気持ちが弱まることがあるのですか？', '["関心のなさや、迷いを伝えるかもしれないから", "失礼に感じられるから", "彼女を混乱させるから", "会話のペースを落とすから"]'::jsonb, '言葉は関心を示していても、距離はためらいを伝えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('49634200-5e42-4c7d-b10f-352eb5b017a0', 'ja', '駆け引きの始まりでは、なぜ言葉よりもエネルギーが大切なのですか？', '["人がまず反応する、感情のトーンをつくるから", "温かく明るいエネルギーは、相手をより軽やかな気持ちにさせるから", "低いエネルギーは、いつでも自信を伝えるから"]'::jsonb, '人は、内容よりも先に、前向きで引き込まれる気持ちのほうへ動きます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
